// Normalize & Validate: runs once per item.
// Input: the raw webhook payload. Output: a clean lead plus a `valid` flag.
const FREEMAIL = new Set([
  'gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com',
  'proton.me', 'protonmail.com', 'icloud.com', 'aol.com',
]);
const body = $json.body || $json;
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const errors = [];

const company = str(body.company);
if (!company) errors.push('company is required');

// "https://www.Fly.io/pricing?x=1" -> "fly.io"
const domain = str(body.domain)
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .split('/')[0]
  .split('?')[0];
if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(domain)) {
  errors.push('domain is missing or not a valid hostname');
}

// GitHub org: explicit value wins. If not provided, record that so the
// downstream scrape branch can try to find the real org from the homepage.
// We still derive a best-guess from the domain as a last-resort fallback,
// but we mark it so the pipeline knows to scrape first.
const explicitOrg = str(body.github_org).toLowerCase();
let githubOrg = explicitOrg;
let githubOrgExplicit = !!explicitOrg;
if (!githubOrg && domain) githubOrg = domain.split('.')[0];
if (!/^[a-z0-9](?:[a-z0-9-]{0,37}[a-z0-9])?$/.test(githubOrg)) {
  errors.push('could not derive a valid GitHub org name');
}

// Email is optional, but if present it has to look real.
const email = str(body.contact_email).toLowerCase();
let emailFreemail = false;
let emailDomainMatch = null;
if (email) {
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.push('contact_email is not a valid address');
  } else {
    const emailDomain = email.split('@')[1];
    emailFreemail = FREEMAIL.has(emailDomain);
    emailDomainMatch = emailDomain === domain || emailDomain.endsWith('.' + domain);
  }
}

return {
  json: {
    valid: errors.length === 0,
    errors,
    company,
    domain,
    // If the caller provided an explicit org, use it directly.
    // If not, set github_org to null so the scrape branch fires.
    // The domain-derived guess is kept as a hint of last resort in 05_extract_github.js.
    github_org: githubOrgExplicit ? githubOrg : null,
    github_org_hint: githubOrgExplicit ? null : githubOrg,
    github_org_explicit: githubOrgExplicit,
    contact_name: str(body.contact_name) || null,
    contact_email: email || null,
    source: str(body.source) || 'unknown',
    email_freemail: emailFreemail,
    email_domain_match: emailDomainMatch,
    received_at: new Date().toISOString(),
  },
};

// Extract GitHub Org: runs only when github_org was not given in the request.
// The previous HTTP Request node fetched the company homepage. Its output holds only the
// HTTP response ($json.body), NOT the lead, so the lead is read back from "Normalize & Validate".
//
// We scan the HTML for github.com/<org> links, keep only orgs that look like they belong to
// THIS company (name or domain match), and pick the most cited. A page that links to
// github.com/actions/checkout three times must not make "actions" the lead's org.
// If nothing matches, fall back to the domain-derived hint (source = domain_hint).

const resp = $json;
let lead = {};
try { lead = $('Normalize & Validate').item.json; } catch (e) { lead = {}; }

const html = (typeof resp.body === 'string' ? resp.body : '') +
             (typeof resp.data === 'string' ? resp.data : '');

// Top-level github.com paths that are GitHub's own pages, not organizations.
const RESERVED = new Set(['about', 'advisories', 'apps', 'blog', 'codespaces', 'collections',
  'contact', 'copilot', 'customer-stories', 'discussions', 'enterprise', 'events', 'explore',
  'features', 'github', 'issues', 'join', 'login', 'marketplace', 'mobile', 'new',
  'notifications', 'organizations', 'orgs', 'pricing', 'pulls', 'readme', 'resources',
  'search', 'security', 'sessions', 'settings', 'signup', 'site', 'solutions', 'sponsors',
  'stars', 'team', 'teams', 'topics', 'trending', 'users', 'watching', 'why-github']);

const norm = (x) => String(x || '').toLowerCase().replace(/[^a-z0-9]/g, '');

// Name-like words for this company: the domain's main label and the company name.
function companyLabels(domain, company) {
  const parts = String(domain || '').toLowerCase().replace(/^www\./, '').split('.').filter(Boolean);
  let sld = parts.length >= 2 ? parts[parts.length - 2] : (parts[0] || '');
  if (['co', 'com', 'org', 'net', 'ac', 'gov', 'edu'].includes(sld) && parts.length >= 3) sld = parts[parts.length - 3];
  return [norm(sld), norm(company)].filter((l) => l.length >= 3);
}

function related(org, labels) {
  const o = norm(org);
  return labels.some((l) => {
    if (o.includes(l)) return true;                       // e2b-dev contains e2b
    if (o.length >= 4 && l.includes(o)) return true;      // datadog in datadoghq
    let i = 0;
    while (i < o.length && i < l.length && o[i] === l[i]) i++;
    return i >= 5 && i / Math.min(o.length, l.length) >= 0.6;  // cockroachdb ~ cockroachlabs
  });
}

const ORG = '([a-zA-Z0-9](?:[a-zA-Z0-9-]{0,37}[a-zA-Z0-9])?)';
// (?:^|[^a-zA-Z0-9.-]) keeps out look-alikes such as notgithub.com and gist.github.com.
const PREFIX = '(?:^|[^a-zA-Z0-9.-])(?:www\\.)?github\\.com\\/';
const patterns = [
  new RegExp(PREFIX + '(?:orgs|sponsors)\\/' + ORG, 'g'),  // github.com/orgs/<org>, /sponsors/<org>
  new RegExp(PREFIX + ORG, 'g'),                            // github.com/<org>
];

const counts = {};
for (const re of patterns) {
  let m;
  while ((m = re.exec(html)) !== null) {
    const org = m[1].toLowerCase();
    if (!RESERVED.has(org)) counts[org] = (counts[org] || 0) + 1;
  }
}

const labels = companyLabels(lead.domain, lead.company);
const best = Object.entries(counts)
  .filter(([org]) => related(org, labels))
  .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0];
const discovered = best ? best[0] : null;

// Last resort: the domain-derived hint from the normalizer, so we still try the GitHub API.
const hint = lead.github_org_hint || null;
const resolvedOrg = discovered || hint || null;
const resolvedSource = discovered ? 'scraped' : (hint ? 'domain_hint' : 'unknown');

return {
  json: {
    ...lead,
    github_org: resolvedOrg,
    github_source: resolvedSource,
  },
};

// Compute Signals: runs once per item, after the GitHub HTTP call.
// Turns the raw repo list into a few facts and a deterministic baseline score.

// When the scrape fallback branch ran, Extract GitHub Org has the real github_org and github_source.
// When the direct branch ran, that node was never executed, so we fall back to Normalize & Validate.
let lead = $('Normalize & Validate').item.json;
try {
  const scraped = $('Extract GitHub Org').item.json;
  if (scraped && scraped.github_org) {
    lead = { ...lead, github_org: scraped.github_org, github_source: scraped.github_source };
  }
} catch (e) { /* direct path: Extract GitHub Org did not run this execution */ }

const res = $json;

// ICP settings come from config/*.toml; build_workflow.py writes them in at build time.
const ICP = {"name": "dev-infra", "description": "Developer-infrastructure buyers: cloud, serverless, sandboxed compute (v1 default, the Unikraft-style ICP).", "scoring": {"tier_cutoffs": [10, 25, 45, 65], "points_per_active_repo": 5, "hot_threshold": 4, "review_gap": 2, "caps": {"activity": 25, "keywords": 40, "languages": 15, "traction": 20}}, "keywords": {"unikernel": 15, "hypervisor": 10, "microvm": 12, "firecracker": 12, "serverless": 8, "wasm": 8, "webassembly": 8, "sandbox": 6, "paas": 6, "ebpf": 6, "kubernetes": 6, "k8s": 6, "container": 5, "docker": 4, "runtime": 4, "edge": 4, "infrastructure": 4, "cloud": 3, "observability": 3, "rust": 3}, "languages": {"Rust": 6, "Go": 6, "C": 6, "C++": 5, "Zig": 4, "TypeScript": 2, "Python": 2}, "prompt": {"product": "Unikraft sells a cloud platform built around unikernels: millisecond boot times, high density, low cost per instance.", "good_fit": "Good-fit companies build or run infrastructure, developer platforms, serverless or edge compute, sandboxed code execution (CI, AI agent sandboxes), or any workload where cold starts and compute cost matter.", "poor_fit": "Poor-fit companies mainly use software rather than build infrastructure (retail, consulting, banks, manufacturers).", "top_of_scale": "strong fit with visible infrastructure work"}, "hash": "06d5dbab"};
const KEYWORDS = ICP.keywords;
const LANGUAGES = ICP.languages;
const TIER_CUTOFFS = ICP.scoring.tier_cutoffs; // rule_score below each cutoff -> tier 1..4, else 5
const CAPS = ICP.scoring.caps;

const status = typeof res.statusCode === 'number' ? res.statusCode : 0;
const repos = status === 200 && Array.isArray(res.body) ? res.body : [];
const own = repos.filter((r) => !r.fork && !r.archived);

let dataQuality;
if (status === 200) dataQuality = own.length > 0 ? 'ok' : 'no_repos';
else if (status === 404) dataQuality = 'no_github';
else if (status === 403 || status === 429) dataQuality = 'rate_limited';
else dataQuality = 'error';

const cutoff = Date.now() - 90 * 24 * 3600 * 1000;
const active90 = own.filter((r) => r.pushed_at && Date.parse(r.pushed_at) >= cutoff);
const starsTotal = own.reduce((n, r) => n + (r.stargazers_count || 0), 0);

const langCount = {};
for (const r of own) if (r.language) langCount[r.language] = (langCount[r.language] || 0) + 1;
const topLanguages = Object.entries(langCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 3)
  .map(([name]) => name);

const text = own
  .map((r) => [r.name, r.description || '', ...(r.topics || [])].join(' '))
  .join(' ')
  .toLowerCase();
const keywordHits = Object.keys(KEYWORDS).filter((k) =>
  new RegExp('\\b' + k + 's?\\b').test(text));

const topRepos = [...own]
  .sort((a, b) => (b.stargazers_count || 0) - (a.stargazers_count || 0))
  .slice(0, 3)
  .map((r) => ({
    name: r.name,
    stars: r.stargazers_count || 0,
    description: (r.description || '').slice(0, 120),
  }));

const activityPts = Math.min(CAPS.activity, active90.length * ICP.scoring.points_per_active_repo);
const keywordPts = Math.min(CAPS.keywords, keywordHits.reduce((n, k) => n + KEYWORDS[k], 0));
const languagePts = Math.min(CAPS.languages, topLanguages.reduce((n, l) => n + (LANGUAGES[l] || 0), 0));
const tractionPts = Math.min(CAPS.traction, Math.round(Math.log10(starsTotal + 1) * 5));
const ruleScore = dataQuality === 'ok' ? activityPts + keywordPts + languagePts + tractionPts : 0;
const ruleTier = TIER_CUTOFFS.filter((c) => ruleScore >= c).length + 1;

return {
  json: {
    ...lead,
    github_status: status,
    data_quality: dataQuality,
    signals: {
      original_repos: own.length,
      active_repos_90d: active90.length,
      stars_total: starsTotal,
      top_languages: topLanguages,
      keyword_hits: keywordHits,
      top_repos: topRepos,
    },
    rule_breakdown: { activityPts, keywordPts, languagePts, tractionPts },
    rule_score: ruleScore,
    rule_tier: ruleTier,
  },
};

// Build Prompt: runs once per item. Only leads with real GitHub data get here.
const s = $json;

// ICP settings come from config/*.toml; build_workflow.py writes them in at build time.
const ICP = {"name": "dev-infra", "description": "Developer-infrastructure buyers: cloud, serverless, sandboxed compute (v1 default, the Unikraft-style ICP).", "scoring": {"tier_cutoffs": [10, 25, 45, 65], "points_per_active_repo": 5, "hot_threshold": 4, "review_gap": 2, "caps": {"activity": 25, "keywords": 40, "languages": 15, "traction": 20}}, "keywords": {"unikernel": 15, "hypervisor": 10, "microvm": 12, "firecracker": 12, "serverless": 8, "wasm": 8, "webassembly": 8, "sandbox": 6, "paas": 6, "ebpf": 6, "kubernetes": 6, "k8s": 6, "container": 5, "docker": 4, "runtime": 4, "edge": 4, "infrastructure": 4, "cloud": 3, "observability": 3, "rust": 3}, "languages": {"Rust": 6, "Go": 6, "C": 6, "C++": 5, "Zig": 4, "TypeScript": 2, "Python": 2}, "prompt": {"product": "Unikraft sells a cloud platform built around unikernels: millisecond boot times, high density, low cost per instance.", "good_fit": "Good-fit companies build or run infrastructure, developer platforms, serverless or edge compute, sandboxed code execution (CI, AI agent sandboxes), or any workload where cold starts and compute cost matter.", "poor_fit": "Poor-fit companies mainly use software rather than build infrastructure (retail, consulting, banks, manufacturers).", "top_of_scale": "strong fit with visible infrastructure work"}, "hash": "06d5dbab"};
const icpText = [ICP.prompt.product, ICP.prompt.good_fit, ICP.prompt.poor_fit].join(' ');

const system = [
  'You score inbound B2B leads for a sales team. You only use the facts provided.',
  'Never invent products, customers, funding, headcount or numbers that are not in the facts.',
  'Ideal customer profile: ' + icpText,
  'Reply with one JSON object and nothing else, using exactly these keys:',
  '{"score": integer 1-5, "confidence": "low"|"medium"|"high", "reason": string (max 25 words, cite the facts used),',
  '"opener": string (max 30 words, a plain first line for a cold email that references one real fact, no flattery)}',
  'Scale: 1 = clearly not a fit, 3 = unclear, 5 = ' + ICP.prompt.top_of_scale + '.',
].join('\n');

// false is substituted at build time by build_workflow.py.
// Set to true with --hide-keyword-hits to test whether the model judges better
// from repo names/descriptions alone, without the rule-stage keyword list.
const hideKeywordHits = false;

const { keyword_hits: _dropped, ...signalsWithout } = s.signals;
const facts = {
  company: s.company,
  domain: s.domain,
  github_org: s.github_org,
  ...(hideKeywordHits ? signalsWithout : s.signals),
};

// Provider-neutral: the HTTP node wraps these in the right request shape (Claude or Groq).
return {
  json: {
    ...s,
    llm_system: system,
    llm_user: 'Lead facts:\n' + JSON.stringify(facts, null, 2),
  },
};

// Parse & Merge: runs once per item. Combines the LLM answer with the rule score
// and never lets a bad model response break the pipeline.
// ICP settings come from config/*.toml; build_workflow.py writes them in at build time.
const ICP = {"name": "dev-infra", "description": "Developer-infrastructure buyers: cloud, serverless, sandboxed compute (v1 default, the Unikraft-style ICP).", "scoring": {"tier_cutoffs": [10, 25, 45, 65], "points_per_active_repo": 5, "hot_threshold": 4, "review_gap": 2, "caps": {"activity": 25, "keywords": 40, "languages": 15, "traction": 20}}, "keywords": {"unikernel": 15, "hypervisor": 10, "microvm": 12, "firecracker": 12, "serverless": 8, "wasm": 8, "webassembly": 8, "sandbox": 6, "paas": 6, "ebpf": 6, "kubernetes": 6, "k8s": 6, "container": 5, "docker": 4, "runtime": 4, "edge": 4, "infrastructure": 4, "cloud": 3, "observability": 3, "rust": 3}, "languages": {"Rust": 6, "Go": 6, "C": 6, "C++": 5, "Zig": 4, "TypeScript": 2, "Python": 2}, "prompt": {"product": "Unikraft sells a cloud platform built around unikernels: millisecond boot times, high density, low cost per instance.", "good_fit": "Good-fit companies build or run infrastructure, developer platforms, serverless or edge compute, sandboxed code execution (CI, AI agent sandboxes), or any workload where cold starts and compute cost matter.", "poor_fit": "Poor-fit companies mainly use software rather than build infrastructure (retail, consulting, banks, manufacturers).", "top_of_scale": "strong fit with visible infrastructure work"}, "hash": "06d5dbab"};
const s = $('Compute Signals').item.json;
const githubSource = s.github_source || 'provided';
const res = $json;

function extractJson(text) {
  if (typeof text !== 'string') return null;
  const t = text.replace(/```(?:json)?/gi, '');
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a === -1 || b <= a) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return null; }
}

function validate(o) {
  if (!o || typeof o !== 'object') return null;
  const score = Math.round(Number(o.score));
  if (!Number.isFinite(score) || score < 1 || score > 5) return null;
  const confidence = ['low', 'medium', 'high'].includes(o.confidence) ? o.confidence : 'low';
  const reason = typeof o.reason === 'string' ? o.reason.trim().slice(0, 300) : '';
  let opener = typeof o.opener === 'string' ? o.opener.trim().slice(0, 300) : '';
  // Grounding check: every number in the opener must appear in the facts we sent.
  const factsText = JSON.stringify(s.signals);
  const numbers = opener.match(/\d[\d,.]*/g) || [];
  const grounded = numbers.every((n) => factsText.includes(n.replace(/[.,]$/, '')));
  if (!grounded) opener = '';
  return { score, confidence, reason, opener: opener || null, opener_dropped: !grounded };
}

let llm = null;
let llmStatus = 'skipped';
let parseHint = '';
if (s.data_quality === 'ok') {
  // Groq / OpenAI-style: choices[0].message.content. Claude: content[0].text.
  const text =
    (res && res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) ||
    (res && res.content && res.content[0] && res.content[0].text) ||
    '';
  llm = validate(extractJson(text));
  const fin = res && res.choices && res.choices[0] && res.choices[0].finish_reason;
  parseHint = 'finish_reason=' + (fin || 'n/a') + ' text=' + String(text).slice(0, 120);
  if (llm) llmStatus = 'ok';
  else if (res && (res.error || res.type === 'error')) llmStatus = 'api_error';
  else llmStatus = 'parse_error';
}

// Short, single-line error text for debugging. Never stored in the database.
let llmError = null;
if (llmStatus === 'api_error') {
  const e = res.error;
  const msg = (e && (e.message || (typeof e === 'string' ? e : ''))) || res.message || 'unknown error';
  llmError = String(msg).replace(/\s+/g, ' ').slice(0, 200);
} else if (llmStatus === 'parse_error') {
  llmError = parseHint.replace(/\s+/g, ' ').slice(0, 200);
}

let status;
let finalScore = null;
let scoreSource = null;
if (s.data_quality === 'ok') {
  status = 'scored';
  finalScore = llm ? llm.score : s.rule_tier;
  scoreSource = llm ? 'llm' : 'rules_fallback';
} else if (s.data_quality === 'no_github' || s.data_quality === 'no_repos') {
  status = 'no_github_data';
} else {
  status = 'needs_retry';
}

const needsReview = !!llm && Math.abs(llm.score - s.rule_tier) >= ICP.scoring.review_gap;

// Usage for cost tracking. Groq/OpenAI: prompt_tokens/completion_tokens. Claude: input_tokens/output_tokens.
// Only the final successful attempt is counted; tokens from retried failures are not visible here.
const usage = (res && res.usage) || {};
const tokensIn = Number(usage.prompt_tokens != null ? usage.prompt_tokens : usage.input_tokens) || null;
const tokensOut = Number(usage.completion_tokens != null ? usage.completion_tokens : usage.output_tokens) || null;
const llmModel = res && typeof res.model === 'string' ? res.model : null;

return {
  json: {
    company: s.company,
    domain: s.domain,
    github_org: s.github_org,
    github_source: githubSource,
    contact_name: s.contact_name,
    contact_email: s.contact_email,
    source: s.source,
    email_freemail: s.email_freemail,
    status,
    final_score: finalScore,
    score_source: scoreSource,
    llm_status: llmStatus,
    llm_error: llmError,
    llm_model: llmModel,
    llm_tokens_in: tokensIn,
    llm_tokens_out: tokensOut,
    llm_score: llm ? llm.score : null,
    llm_confidence: llm ? llm.confidence : null,
    reason: llm ? llm.reason : null,
    opener: llm ? llm.opener : null,
    opener_dropped: llm ? llm.opener_dropped : false,
    rule_score: s.rule_score,
    rule_tier: s.rule_tier,
    needs_review: needsReview,
    hot: finalScore !== null && finalScore >= ICP.scoring.hot_threshold,
    icp: ICP.name + '@' + ICP.hash,
    signals: s.signals,
  },
};
